INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (1,  'd2351fc5e5e947a682729eb39ab4ac57', 'This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times.', 'introduction', '2022-04-23 00:47:15.03029');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (3,  '8d48cbb53cf2427a89f31438058adc96', 'Please click the link to view the latest Personal & Financial Review document.', 'profile_fact_find', '2022-04-23 00:47:15.105672');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (4,  '0c1fb57d8b174f7a98a15b9aa7c7c47f', 'Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below.', 'profile_risk', '2022-04-23 00:47:15.146787');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (15, '711ee597f8164d0bb09e0b463f74bfb0', '<p>Your advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.</p>', 'conclusions_action_points', '2022-04-28 20:56:34.190393');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (6,  '1d43db6d83854328b71d23a07804b17e', '<p>The value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.</p>', 'policy_valuations', '2022-04-23 00:47:15.225294');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (7,  '196f22cf00a34e4a953fa3a978c98146', '<p>Any assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.</p>', 'fees', '2022-04-23 00:47:15.264139');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (9,  'a39ac58e28494d3496cd2a15144efce4', '<p>Each investment platform or policy provider has their own set of fees. These are detailed below.</p>', 'fees_policy_fees', '2022-04-23 00:47:15.341756');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (10, 'b505d8dad0c3422281b3d99a675fe1ff', '<p>Each of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.</p>', 'fees_fund_level', '2022-04-23 00:47:15.38145');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (14, '9c74fdc1229b4ca6ae0ca5ba5ee3897d', '<p>Discretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.</p>', 'fees_dim', '2022-04-28 20:52:26.714025');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (11, '74a6e5b705a645faa380d90454347f6d', '<p>Each of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.</p><p>The charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).</p>', 'fees_portfolio_level', '2022-04-23 00:47:15.421807');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (16, '9115ca2675b8413f836f97ebad020451', '<p><strong><em>Advisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.</em></strong></p><p><br></p><p>Your .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.</p>', 'conclusions_ongoing_suitability', '2022-04-28 21:03:50.124173');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (12, 'b6a66941000841c788d1879c041aa646', '<p>Integral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.</p><p>Please refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.</p><p>Finally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.</p>', 'conclusions_due_diligence', '2022-04-24 19:05:23.553975');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (2,  '2f4ee8dd151149749e28b2fb822197b8', '<p>The ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.</p>', 'profile', '2022-04-23 00:47:15.069034');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (17, 'a9225d8eba0e4bf6ab82dde7e6c2fba9', '<p><strong><em>Delete the following paragraphs as appropriate and add further detail if there are specific objectives:</em></strong></p><p><br></p><p>During our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.</p><p><br></p><p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.</p><p><br></p><p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', 'conclusions_goals', '2022-05-17 18:32:25.29393');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (5,  '491ad09f9d1c4ba18b0f9d23aee9576a', '<p>We have identified some overall aims and goals for your financial planning. The details of these are listed below.</p><p><br></p><ul><li>Although you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.</li><li>To reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.</li><li>You are keen to make use of the tax allowances and reliefs which are available to you.</li><li>You wish to meet your long term goals by investing for capital growth.</li><li>You are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.</li></ul>', 'profile_objectives', '2022-04-23 00:47:15.185633');
INSERT INTO public.module_presets (id, uid, text, module_type, "timestamp") OVERRIDING SYSTEM VALUE VALUES (8,  '1bbc749eabb242799d07cab633279cd5', '<p>The Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.</p><p>The table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.</p><p>Actual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).</p>', 'fees_advice_fee', '2022-04-23 00:47:15.303003');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (1, 1, 'conclusions_due_diligence', '<p>Integral Advice periodically assesses the quality of the providers which you are using. blah</p>', '<p>However, in your case, we don''t actually give a toss.</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (30, 1, 'introduction', '', '<p>test</p><p><br></p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (6, 4, 'conclusions_ongoing_suitability', '<p>Your Aegon platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. You pension has allowed you to claim tax relief on contributions. The money in both your pension and ISA grow in a tax efficient environment. Your General Investment Account, whilst not tax efficient, allows you to make use of your Capital Gains Tax allowance.</p><p><br></p><p>All three products enable the use of Model Portfolio Services from Discretionary Investment Managers. This means that the portfolios are diverse and managed to a specific risk remit.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (7, 4, 'conclusions_advice_given', '', '<p>We have discussed your situation over the review period. On the basis of these discussions, I have not made any specific recommendations to make changes to your portfolio since our last review.</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (13, 5, 'conclusions_ongoing_suitability', '<p>Your Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. You pension has allowed you to claim tax relief on contributions. The money in both your pension and ISA grow in a tax efficient environment. Your General Investment Account, whilst not tax efficient, allows you to make use of your Capital Gains Tax allowance.</p><p><br></p><p>All three products enable the use of Model Portfolio Services from Discretionary Investment Managers. This means that the portfolios are diverse and managed to a specific risk remit.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (15, 5, 'conclusions_action_points', '<p>Your advice requirements are currently up to date, and there is nothing to action at this stage. We did discuss your proposal to move house in the near future. When you are ready to discuss this in more detail, please do get in touch as I will be happy to provide appropriate mortgage advice.</p><p><br></p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (16, 5, 'conclusions_advice_given', '<p>Although we have not made any changes to your portfolio since our last review, we have discussed your situation. You told me about your upcoming wedding and the anticipated costs. With this in mind, we decided not to commit further funds to investment at this time.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (17, 4, 'profile_objectives', '', '<p><br></p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (38, 2, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.</p><p>You have confirmed that you are happy with the generalised nature of your financial planning thus far.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (8, 4, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', '<p><br></p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (34, 2, 'conclusions_forecast', '<p>This section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (14, 5, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', '<p><br></p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (26, 6, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (28, 6, 'conclusions_advice_given', '<p>Since the last review, I recommended that you top up your existing pension with a single contribution and increase your regular contributions.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (27, 6, 'conclusions_ongoing_suitability', '<p>Your Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. They both enable the use of Model Portfolio Services from Discretionary Investment Managers. Aviva is one of the few providers who also allow you to split a single investment product over two different portfolios.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.</p>', '<p>(Please note that you still have £685.83 in the LF Equity Income C Acc fund within your ISA. This fund sits outside of any model. It is a closed fund, and as such, cannot be traded out of.)</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (35, 2, 'conclusions_advice_given', '', '<p>Over the last year I have given you advice on the following specific points:</p><p><br></p><ul><li>Topping up your ISA</li><li>Setting up a new GIA</li></ul><p>We have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (40, 2, 'conclusions_due_diligence', '<p>Integral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your use of Aviva, Aegon, LGT Vestra and Tatton Investment Management.</p><p>Please refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.</p><p>Finally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (32, 2, 'conclusions_ongoing_suitability', '<p>Your policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (3, 2, 'introduction', '<p>blah</p>', '<p><br></p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (43, 7, 'fees_advice_fee', '', '<p>Please note that, due to a logging error, the fees which have actually been received in relation to your pension do not appear in the linked file. This error has now been rectified, so the actual fees received (including those received to date) will appear on any future reports.</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (44, 7, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (45, 7, 'conclusions_ongoing_suitability', '<p>Your Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. Both products enable the use of Model Portfolio Services from Discretionary Investment Managers.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (46, 7, 'conclusions_advice_given', '<ul><li>I reviewed your existing pensions and I advised that you transfer them to a new policy on the Aviva platform.</li><li>I recommended that you invest £10,000 of the money you were holding on deposit for medium to long term capital growth in a Stocks and Shares ISA, also on the Aviva platform.</li><li>I recommended you commence regular contributions to both arrangements.</li></ul><p><br></p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (47, 8, 'conclusions_goals', '<p>During our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.</p><p><br></p><p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.</p><p><br></p><p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (48, 8, 'conclusions_ongoing_suitability', '<p>Your Aviva platform pension is a suitable vehicle to help you to meet your goals. Pensions are a tax efficient method of investing for the future. The Aviva scheme allows you to utilise the services of Model Portfolio Services (MPSs) from Discretionary Investment Managers. The Aviva platform is one of the few such platforms which enable the use of multiple MPSs within a single product.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (50, 8, 'conclusions_due_diligence', '<p>Integral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse use of Aviva, Tatton and LGT Vestra WM.</p><p>Please refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.</p><p>Finally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (51, 8, 'conclusions_advice_given', '', '<p>Although we have met and discussed your situation over the review period, I did not recommend any changes to the management of your Aviva pension.</p><p><br></p><p>(We did discuss your intention to increase pension investment, but we felt that this was best done through your workplace scheme at this time).</p>');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (52, 8, 'profile_objectives', '<p>We have identified some overall aims and goals for your financial planning. The details of these are listed below.</p><p><br></p><ul><li>Although you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your early 60s. That said, you may wish to continue working in a part-time capacity after that point.</li><li>To reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.</li><li>You are keen to make use of the tax allowances and reliefs which are available to you.</li><li>You wish to meet your long term goals by investing for capital growth.</li><li>You are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.</li></ul>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (42, 7, 'profile_objectives', '<p>We have identified some overall aims and goals for your financial planning. The details of these are listed below.</p><p><br></p><ul><li>You have said that, ideally, you would like to aim for a retirement age of 60, but you realise that that may be unrealistic. Although you do not have a specific date in mind for retirement, you would still like to make financial plans for it.</li><li>To reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.</li><li>You are keen to make use of the tax allowances and reliefs which are available to you.</li><li>You wish to meet your long term goals by investing for capital growth.</li><li>You are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.</li></ul>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (55, 7, 'conclusions_due_diligence', '<p>Integral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse the continued use of Aviva, Brewin Dolphin and IBOSS Asset Management.</p><p>Please refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.</p><p>Finally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (56, 10, 'conclusions_goals', '<p>Although we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.&nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (57, 10, 'conclusions_ongoing_suitability', '<p>Your policies are all suitable vehicles to help you to meet your goals. The Aegon ARC pension and ISA are both tax efficient wrappers. (The GIA is taxable but there is only a residual amount of money held in this wrapper). All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.</p><p><br></p><p>The Aviva pensions, whilst not as flexible as the Aegon ones, are still appropriate tax efficient methods of investing for the long term benefit of your children.</p><p><br></p><p>For further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (58, 10, 'conclusions_due_diligence', '<p>Integral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse the use of Aviva, Aegon and Tatton Investment Management.</p><p>Please refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.</p><p>Finally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (59, 10, 'conclusions_advice_given', '<p>Although we have spoken and discussed your situation, I have not made any specific recommendations for changes to your portfolio over the review period.</p>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (61, 10, 'profile_objectives', '<p>We have identified some overall aims and goals for your financial planning. The details of these are listed below.</p><p><br></p><ul><li>Although you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.</li><li>To reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.</li><li>You are keen to make use of the tax allowances and reliefs which are available to you.</li><li>You wish to meet your long term goals by investing for capital growth.</li><li>You are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.</li><li>You would also like to make some investments on behalf of your children to give them a headstart with their own financial planning.</li></ul>', '');
INSERT INTO public.modules (id, client_id, type, intro, text) OVERRIDING SYSTEM VALUE VALUES (62, 10, 'conclusions_action_points', '<p>We discussed various plans, which you would like to implement later in the year, once you have received your next profit distribution:</p><ul><li>You would like to increase the payments you are making on a regular basis to your children''s pensions. We also discussed transferring these policies to a more modern, platform based policy, which would allow you to use model portfolio services for these investments in the same way that you do for your own investments.</li><li>You are intending to make an overpayment to your mortgage.</li><li>Subject to budget, you may also want to invest more money on a single contribution basis.</li></ul><p>Right now, your advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.</p>', '');
INSERT INTO public.policy_providers (id, uid, name, pricing, custom_pricing, "timestamp") OVERRIDING SYSTEM VALUE VALUES (4, '4ebdb61927e84a9d97b0e77ca7d6c211', 'Aviva', '<p>Aviva''s product fee for their personal pension is 0.7% per year. This is discounted based on the fund size according to the following table:</p><p>Fund size (£)			Discount (% points)</p><p>0-£19,999				0.00</p><p>£19,000-£29,999	0.25</p><p>£30,000-£49,999	0.25</p><p>£50,000-£99,000	0.30</p><p>£100,000	or more	0.30</p>', '', '2022-08-03 09:12:14.14192');
INSERT INTO public.policy_providers (id, uid, name, pricing, custom_pricing, "timestamp") OVERRIDING SYSTEM VALUE VALUES (2, '78e94fd5ec6e4a40aad451eed77a628c', 'Aegon', '<p>Aegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.</p><p>{{ table }}</p>', '', '2022-05-02 22:17:49.337705');
INSERT INTO public.policy_providers (id, uid, name, pricing, custom_pricing, "timestamp") OVERRIDING SYSTEM VALUE VALUES (1, 'b7f8f4e5104043429c5993be7fdf930d', 'Aviva Wrap', '<p>Aviva levy a platform fee for their pensions, on a tiered basis, according to the following table:</p><p>{{ table }}</p><p><br></p><p>For ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.</p>', '<p>In your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of<strong> {{ charge }}%</strong> per year.</p>', '2022-04-23 00:47:15.995507');
