,"Filename":""}},{"Id":"3faa08a399f64d4b9f869b24c42aa5a4","Name":"Jupiter Balanced","OcfFee":0.76,"ExAnteFee":0.16,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"57083349d3404a02967c260a29f13abe","FundId":"3faa08a399f64d4b9f869b24c42aa5a4","PolicyId":"1e328d3daa2844cfb8e61475e2b93e5d","Proportion":0.15},{"Id":"a79e65a532cf490689ff008ab13725f6","FundId":"3e4bc95d83fa41b2861df9a4ec41a1bd","PolicyId":"432750f27b7343a0bccfbf19b50937a4","Proportion":0.15},{"Id":"639c6191b08747b4a79fa92cd6724e67","FundId":"3f6a15381afc4fee88dbbd0206eb3bdb","PolicyId":"432750f27b7343a0bccfbf19b50937a4","Proportion":0.32},{"Id":"771067c051574a19b3c14c5c1cfef0ae","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"432750f27b7343a0bccfbf19b50937a4","Proportion":0.25},{"Id":"dad164746c5c490caf27c0bc9fc2b1f4","FundId":"4c6f2e04f4204cc484563b2ad30b5dd6","PolicyId":"432750f27b7343a0bccfbf19b50937a4","Proportion":0.13},{"Id":"24583f5e324a4645869eb20fa31aafa8","FundId":"3faa08a399f64d4b9f869b24c42aa5a4","PolicyId":"432750f27b7343a0bccfbf19b50937a4","Proportion":0.15}],"Operators":[{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015},{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002}],"Models":[{"Id":"0","Name":"LGT Vestra Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}},{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}},{"Id":"1","Name":"LGT WMAdventurous","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.74,"WeightedExAnteFee":0.14,"Modified":"2022-05-20T00:00:00Z","File":{"Uid":"650dd8104504479497d6d8708b805952","Filename":"LGT WM Adventurous.pdf"}}],"Portfolios":[{"Id":"761dcc9457c5418bace91821a4efeecb","PolicyId":"1e328d3daa2844cfb8e61475e2b93e5d","ModelId":"0","Proportion":1},{"Id":"ee0e475ab10e466c9e2b20107e11c50a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"2","Proportion":0.4},{"Id":"d0ea24231c86494d880d38730e5a3f0a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"1","Proportion":0.6}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"76d9f542b3d44e19b74c8276dc3d9ece","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":4,"Label":"4 of 10 - Lowest Medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘lowest medium’ risk profile shows that your willingness and ability to accept investment risk is just below average. A portfolio matching this risk profile is likely to experience both rises and falls in value. So, while there is potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly low- and medium-risk investments, including money market investments, government bonds, Sterling corporate bonds, and a mix of global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares but held mainly in UK and other developed markets. Small amounts in other higher-risk investments may also be included. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"939a3b96046e446c8d633ed937d878ab","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"76d9f542b3d44e19b74c8276dc3d9ece","Completed":"2022-05-18T00:00:00Z","Questionnaire":{"Uid":"764a9e65cfd049b08ad51c68db47cc04","Filename":"sample.png"}}],"FactFinds":[{"Id":"9c614ebc14604a54a910925507bdc1ca","Submitted":"2022-04-26T00:00:00Z","File":{"Uid":"5cb8b5bd8c69408795ae535660157600","Filename":"PXL_20220408_005403964.jpg"}}],"FeesReports":[{"Id":"6fce555dc0034858bc64bd36235a9661","Submitted":"2022-04-29T00:00:00Z","File":{"Uid":"534944f5567446f582f4b9ba6370cd14","Filename":"PXL_20220408_005429828.MP.jpg"}}],"Forecasts":[]}', '2022-06-01 00:00:00', '2022-08-11 00:00:00', '2022-06-25 06:12:47.496819', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (44, '8ea4239279684eccadc0c40eb803f7d2', 2, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"introduction","Intro":"","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy\u003c/p\u003e","Text":""},{"Type":"conclusions_forecast","Intro":"\u003cp\u003eThis section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eOver the last year I have given you advice on the following specific points:\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eTopping up your ISA\u003c/li\u003e\u003cli\u003eSetting up a new GIA\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eWe have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.\u003c/p\u003e"},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your use of Aviva, Aegon, LGT Vestra and Tatton Investment Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003eYou have confirmed that you are happy with the generalised nature of your financial planning thus far.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"}],"PolicyProviders":[{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""},{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42,"Sequence":0},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55,"Sequence":1},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35,"Sequence":2},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32,"Sequence":3},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":1,"Sequence":4},{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0}],"ProviderDiscounts":[{"Id":"0ec68f1eb6904fc3948fbf6d57aa7364","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"b5c4064889c74ab2b6a5ed2c0b683255","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"123","MonthlyContributions":0,"StartValue":41358,"EndValue":48659,"Notes":"\u003cp\u003eThis policy was transferred to Aegon as part of block transfer. It has protected tax-free cash which is why it couldn''t also be transferred to Aviva\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"4d1d74ff96f745399d68eba1cfe64f13","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"456","MonthlyContributions":0,"StartValue":10000,"EndValue":12000,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"6beaec3191ba47db9e49ec33ac540c00","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"123456","MonthlyContributions":200,"StartValue":121311,"EndValue":132759,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"292975c4738e487c81eb2997a2acbe0b","Filename":"test.txt"}}],"Funds":[{"Id":"338c91a2dcc943f29615148fc8734ff3","Name":"Fundsmith Equity","OcfFee":0.81,"ExAnteFee":0.09,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"057a51200a6a4b4993e9961c07b3d401","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":1}],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"0","Name":"LGT Vestra Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}},{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}}],"Portfolios":[{"Id":"45f2436b75814f9bb8d3dc8b83a77544","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","ModelId":"0","Proportion":1},{"Id":"8d44508721954d708cbf437acd80bba9","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"2","Proportion":0.5},{"Id":"99eb4251f3a44eb59f1316f1ae6d0a64","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"0","Proportion":0.5}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"d84eadecc60f49958d5b90abbfc0809c","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2022-05-03T00:00:00Z","Questionnaire":{"Uid":"6c250cddf3d14468a4a5b4b63137dc88","Filename":"Client Profiling Report.pdf"}}],"FactFinds":[{"Id":"39cec7ea8d0d4abf843efb88de2ae05e","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"224de1f41aa9417aa0341f2601b05941","Filename":"PG FF.pdf"}}],"FeesReports":[{"Id":"46c84ca2478a4b51a0225c17f2865206","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"d7ca6cb0a77d47a2bebe99a3d893349e","Filename":"fees rep.docx"}}],"Forecasts":[{"Id":"79334283414b46829202a2780723fb36","Submitted":"2022-07-13T00:00:00Z","File":{"Uid":"257a1784e0704825adb63cfc3aed26ad","Filename":"chart.pdf"}}]}', '2022-01-17 00:00:00', '2022-07-13 00:00:00', '2022-07-14 07:49:51.074887', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (45, '5ac4a32ca9df437f90bd1bcf25b90fbf', 2, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"introduction","Intro":"\u003cp\u003eblah\u003c/p\u003e","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy\u003c/p\u003e","Text":""},{"Type":"conclusions_forecast","Intro":"\u003cp\u003eThis section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eOver the last year I have given you advice on the following specific points:\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eTopping up your ISA\u003c/li\u003e\u003cli\u003eSetting up a new GIA\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eWe have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.\u003c/p\u003e"},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your use of Aviva, Aegon, LGT Vestra and Tatton Investment Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003eYou have confirmed that you are happy with the generalised nature of your financial planning thus far.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"}],"PolicyProviders":[{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""},{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42,"Sequence":0},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55,"Sequence":1},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35,"Sequence":2},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32,"Sequence":3},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":1,"Sequence":4},{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0}],"ProviderDiscounts":[{"Id":"0ec68f1eb6904fc3948fbf6d57aa7364","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"b5c4064889c74ab2b6a5ed2c0b683255","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"123","MonthlyContributions":0,"StartValue":41358,"EndValue":48659,"Notes":"\u003cp\u003eThis policy was transferred to Aegon as part of block transfer. It has protected tax-free cash which is why it couldn''t also be transferred to Aviva\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"4d1d74ff96f745399d68eba1cfe64f13","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"456","MonthlyContributions":0,"StartValue":10000,"EndValue":12000,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"6beaec3191ba47db9e49ec33ac540c00","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"123456","MonthlyContributions":200,"StartValue":121311,"EndValue":132759,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"292975c4738e487c81eb2997a2acbe0b","Filename":"test.txt"}}],"Funds":[{"Id":"338c91a2dcc943f29615148fc8734ff3","Name":"Fundsmith Equity","OcfFee":0.81,"ExAnteFee":0.09,"Modified":"","File":{"Uid":"","Filename":""}},{"Id":"4c6f2e04f4204cc484563b2ad30b5dd6","Name":"Invesco High Income","OcfFee":0.67,"ExAnteFee":0.11,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"057a51200a6a4b4993e9961c07b3d401","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5},{"Id":"7aeec1c0eea7409f891e618919b9a8f9","FundId":"4c6f2e04f4204cc484563b2ad30b5dd6","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5}],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}},{"Id":"0","Name":"LGT Vestra Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}}],"Portfolios":[{"Id":"45f2436b75814f9bb8d3dc8b83a77544","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","ModelId":"0","Proportion":1},{"Id":"8d44508721954d708cbf437acd80bba9","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"2","Proportion":0.5},{"Id":"99eb4251f3a44eb59f1316f1ae6d0a64","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"0","Proportion":0.5}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"d84eadecc60f49958d5b90abbfc0809c","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2022-05-03T00:00:00Z","Questionnaire":{"Uid":"6c250cddf3d14468a4a5b4b63137dc88","Filename":"Client Profiling Report.pdf"}}],"FactFinds":[{"Id":"39cec7ea8d0d4abf843efb88de2ae05e","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"224de1f41aa9417aa0341f2601b05941","Filename":"PG FF.pdf"}}],"FeesReports":[{"Id":"46c84ca2478a4b51a0225c17f2865206","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"d7ca6cb0a77d47a2bebe99a3d893349e","Filename":"fees rep.docx"}}],"Forecasts":[{"Id":"79334283414b46829202a2780723fb36","Submitted":"2022-07-13T00:00:00Z","File":{"Uid":"257a1784e0704825adb63cfc3aed26ad","Filename":"chart.pdf"}}]}', '2022-07-14 00:00:00', '2022-07-14 00:00:00', '2022-07-14 08:30:31.956783', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (46, '72dd595cd76740288eb0ae1f8ad7c8a0', 2, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"introduction","Intro":"\u003cp\u003eblah\u003c/p\u003e","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy\u003c/p\u003e","Text":""},{"Type":"conclusions_forecast","Intro":"\u003cp\u003eThis section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eOver the last year I have given you advice on the following specific points:\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eTopping up your ISA\u003c/li\u003e\u003cli\u003eSetting up a new GIA\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eWe have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.\u003c/p\u003e"},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your use of Aviva, Aegon, LGT Vestra and Tatton Investment Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003eYou have confirmed that you are happy with the generalised nature of your financial planning thus far.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"},{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0},{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42,"Sequence":0},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55,"Sequence":1},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35,"Sequence":2},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32,"Sequence":3},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":1,"Sequence":4}],"ProviderDiscounts":[{"Id":"0ec68f1eb6904fc3948fbf6d57aa7364","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"b5c4064889c74ab2b6a5ed2c0b683255","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"123","MonthlyContributions":0,"StartValue":41358,"EndValue":48659,"Notes":"\u003cp\u003eThis policy was transferred to Aegon as part of block transfer. It has protected tax-free cash which is why it couldn''t also be transferred to Aviva\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"4d1d74ff96f745399d68eba1cfe64f13","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"456","MonthlyContributions":0,"StartValue":10000,"EndValue":12000,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"6beaec3191ba47db9e49ec33ac540c00","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"123456","MonthlyContributions":200,"StartValue":121311,"EndValue":132759,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"292975c4738e487c81eb2997a2acbe0b","Filename":"test.txt"}}],"Funds":[{"Id":"338c91a2dcc943f29615148fc8734ff3","Name":"Fundsmith Equity","OcfFee":0.81,"ExAnteFee":0.09,"Modified":"","File":{"Uid":"","Filename":""}},{"Id":"4c6f2e04f4204cc484563b2ad30b5dd6","Name":"Invesco High Income","OcfFee":0.67,"ExAnteFee":0.11,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"057a51200a6a4b4993e9961c07b3d401","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5},{"Id":"7aeec1c0eea7409f891e618919b9a8f9","FundId":"4c6f2e04f4204cc484563b2ad30b5dd6","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5}],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"0","Name":"LGT Vestra Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}},{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}}],"Portfolios":[{"Id":"45f2436b75814f9bb8d3dc8b83a77544","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","ModelId":"0","Proportion":1},{"Id":"8d44508721954d708cbf437acd80bba9","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"2","Proportion":0.5},{"Id":"99eb4251f3a44eb59f1316f1ae6d0a64","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"0","Proportion":0.5}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"d84eadecc60f49958d5b90abbfc0809c","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2022-05-03T00:00:00Z","Questionnaire":{"Uid":"6c250cddf3d14468a4a5b4b63137dc88","Filename":"Client Profiling Report.pdf"}}],"FactFinds":[{"Id":"39cec7ea8d0d4abf843efb88de2ae05e","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"224de1f41aa9417aa0341f2601b05941","Filename":"PG FF.pdf"}},{"Id":"2267d2ddd9c6475d93adcc1be58613e9","Submitted":"2022-07-14T00:00:00Z","File":{"Uid":"4f4c6c9025ec48faa8104cc4a1b71473","Filename":"chart.pdf"}}],"FeesReports":[{"Id":"46c84ca2478a4b51a0225c17f2865206","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"d7ca6cb0a77d47a2bebe99a3d893349e","Filename":"fees rep.docx"}}],"Forecasts":[{"Id":"79334283414b46829202a2780723fb36","Submitted":"2022-07-13T00:00:00Z","File":{"Uid":"257a1784e0704825adb63cfc3aed26ad","Filename":"chart.pdf"}}]}', '2022-07-14 00:00:00', '2022-07-14 00:00:00', '2022-07-14 09:48:49.893133', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (28, 'bf259a306ede4be9bf87bd1c89750606', 4, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"The ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and your objectives."},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the policy providers levy the fee monthly.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fee in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour Aegon platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. You pension has allowed you to claim tax relief on contributions. The money in both your pension and ISA grow in a tax efficient environment. Your General Investment Account, whilst not tax efficient, allows you to make use of your Capital Gains Tax allowance.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAll three products enable the use of Model Portfolio Services from Discretionary Investment Managers. This means that the portfolios are diverse and managed to a specific risk remit.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eWe have discussed your situation over the review period. On the basis of these discussions, I have not made any specific recommendations to make changes to your portfolio since our last review.\u003c/p\u003e"},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"profile_objectives","Intro":"","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"}],"PolicyTypes":[{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""}],"ProviderCharges":[{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55},{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":1},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32}],"ProviderDiscounts":[],"Policies":[{"Id":"65e1272cffeb46fc96cc8f7e1595e7a1","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"71298806","MonthlyContributions":0,"StartValue":303872,"EndValue":310844,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"1213ef64f8ca4f60ac0b00de9013bc7a","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"71298805","MonthlyContributions":1666,"StartValue":235632,"EndValue":238386,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"4683cb65f7f14343ac7ba97faf4b9899","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"71298815","MonthlyContributions":0,"StartValue":565907,"EndValue":579925,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":null,"PolicyFunds":[],"Operators":[{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015},{"Id":"02ec4f9c74e54490adb40ed368f0b658","Type":"dim","Name":"FE Invest","Fee":0.0023}],"Models":[{"Id":"5c99ea3ce6e141d29cb9c064ed130a27","Name":"Tatton Core Aggressive","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.36,"WeightedExAnteFee":0.1,"Modified":"2022-05-17 00:00:00 +0000 UTC","File":{"Uid":"08ea3e8578d5499e92b2e7cd6ab01d87","Filename":"Tatton Core Aggessive.pdf"}},{"Id":"c8d2b41aec0841079a2d11fbdd803294","Name":"FE Invest Hybrid Risk Level 5 Long","OperatorId":"02ec4f9c74e54490adb40ed368f0b658","WeightedOcfFee":0.45,"WeightedExAnteFee":0.05,"Modified":"2022-05-17 00:00:00 +0000 UTC","File":{"Uid":"bf06e10d878f4967bce7103395f6a6ac","Filename":"FEI Hybrid Level 5 long term.pdf"}},{"Id":"a78ca1d201b8416693fedeb18fb50a83","Name":"Tatton Core Global Equity","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.32,"WeightedExAnteFee":0.13,"Modified":"2022-05-17 00:00:00 +0000 UTC","File":{"Uid":"82b1221f869a4ad6a3ad326a7f1c17e0","Filename":"Tatton Core Global Equity.pdf"}}],"Portfolios":[{"Id":"4419bc6060414c648a7e9834ecc64482","PolicyId":"65e1272cffeb46fc96cc8f7e1595e7a1","ModelId":"a78ca1d201b8416693fedeb18fb50a83","Proportion":1},{"Id":"f96de0187aaf47c2902abfa443d82e58","PolicyId":"4683cb65f7f14343ac7ba97faf4b9899","ModelId":"5c99ea3ce6e141d29cb9c064ed130a27","Proportion":1},{"Id":"a77a858bdcd14f1baa9c46738095fb08","PolicyId":"1213ef64f8ca4f60ac0b00de9013bc7a","ModelId":"c8d2b41aec0841079a2d11fbdd803294","Proportion":1}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"618df96d50d844db9444b052af397e74","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":7,"Label":"7 of 10 - Highest medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘highest medium’ risk profile shows that your willingness and ability to accept investment risk is well above average. A portfolio that matches this risk profile is likely to experience significant rises and falls in value. So, while there is strong potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly high- and very-high-risk investments, such as UK, overseas developed and emerging market shares. It is also expected to have a small amount of medium-risk investments such as Property as well as Sterling corporate bonds and global bonds including higher income types. Always check that you are comfortable with the investments that are included in your chosen portfolio.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"15db59ebf6a84ad6ac0e5fc543a4c852","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"618df96d50d844db9444b052af397e74","Completed":"2021-02-21","Questionnaire":{"Uid":"561a6ae67680422081069c0989eed0bb","Filename":"Risk Profiling Report.pdf"}}],"FactFinds":[{"Id":"99092eb20a25428ca9b2a8a470f27a81","Submitted":"2022-05-17","File":{"Uid":"a0cbe4e1d57c4d908d15f7bc669cbb48","Filename":"Part 1, v2.pdf"}}],"FeesReports":[{"Id":"6acc91bf79444d08935620569ba0b2d8","Submitted":"2022-05-17","File":{"Uid":"e8caeece48104dadb425d44a68e3e2ca","Filename":"table.docx"}}],"Forecasts":[]}', '2021-05-17 00:00:00', '2022-05-17 00:00:00', '2022-05-20 12:43:34.122412', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (26, '338e153c3dcc43bfb1fe90e460a516d4', 5, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"The ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and your objectives."},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the policy providers levy the fee monthly.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fee in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. You pension has allowed you to claim tax relief on contributions. The money in both your pension and ISA grow in a tax efficient environment. Your General Investment Account, whilst not tax efficient, allows you to make use of your Capital Gains Tax allowance.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAll three products enable the use of Model Portfolio Services from Discretionary Investment Managers. This means that the portfolios are diverse and managed to a specific risk remit.\u003c/p\u003e","Text":""},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"conclusions_action_points","Intro":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. We did discuss your proposal to move house in the near future. When you are ready to discuss this in more detail, please do get in touch as I will be happy to provide appropriate mortgage advice.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"\u003cp\u003eAlthough we have not made any changes to your portfolio since our last review, we have discussed your situation. You told me about your upcoming wedding and the anticipated costs. With this in mind, we decided not to commit further funds to investment at this time.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of {{ charge }}% per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18}],"ProviderDiscounts":[{"Id":"62d4a360e5a64cf0b4ba1b5b5080efb8","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"4eb2f2894d7a4d85bdcfe690c5c205bf","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2437486-003","MonthlyContributions":1050,"StartValue":0,"EndValue":11606,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"3c1372fd187546dba70ab552cdc4e0e8","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2437486-002","MonthlyContributions":1666,"StartValue":63183,"EndValue":115139,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"69c7d1ee916b46a3b0163bf70e415c7e","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2437486-001","MonthlyContributions":0,"StartValue":113745,"EndValue":108893,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":null,"PolicyFunds":[],"Operators":[{"Id":"02ec4f9c74e54490adb40ed368f0b658","Type":"dim","Name":"FE Invest","Fee":0.0023}],"Models":[{"Id":"cb1c2806fca44c2c90f1f68ad1ab9acf","Name":"FE Invest Hybrid Risk Level 3 Long","OperatorId":"02ec4f9c74e54490adb40ed368f0b658","WeightedOcfFee":0.4,"WeightedExAnteFee":0.06,"Modified":"2022-05-20 00:00:00 +0000 UTC","File":{"Uid":"336a20bb89844e8aa01a8ac8068ff72a","Filename":"FE3 H L.pdf"}}],"Portfolios":[{"Id":"c76aad4012e64249a8bdfbd9ea9864e3","PolicyId":"4eb2f2894d7a4d85bdcfe690c5c205bf","ModelId":"cb1c2806fca44c2c90f1f68ad1ab9acf","Proportion":1},{"Id":"191c7d5d18cb4c06a6a92aa473afe6c0","PolicyId":"3c1372fd187546dba70ab552cdc4e0e8","ModelId":"cb1c2806fca44c2c90f1f68ad1ab9acf","Proportion":1},{"Id":"f6a87cbdaa7f47caa130623127f31a35","PolicyId":"69c7d1ee916b46a3b0163bf70e415c7e","ModelId":"cb1c2806fca44c2c90f1f68ad1ab9acf","Proportion":1}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0a03fafd4a034300a48f0c9b781dfbad","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":5,"Label":"5 of 10 - Low medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘low medium’ risk profile shows that your willingness and ability to accept investment risk is about average. A portfolio that matches this risk profile is likely to experience both rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain low-, medium- and high-risk investments, including money market investments, government bonds, Sterling corporate bonds and global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares, but held mainly in UK and other developed markets, and also a small amount in other higher-risk investments such as shares in emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"9a00ec86174f48b5ab3fc288e6d1d1a2","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0a03fafd4a034300a48f0c9b781dfbad","Completed":"2022-04-13","Questionnaire":{"Uid":"17c284d75c574b6e99f2f3fbd37d7f8b","Filename":"Risk_profile.pdf"}}],"FactFinds":[{"Id":"c843b6cbb650470ea2345ef9008192d9","Submitted":"2022-05-20","File":{"Uid":"61c5d117a83c4e0182f37e7bff6d1cf1","Filename":"Fact find only.pdf"}}],"FeesReports":[{"Id":"58d2b24f14e4401b85ba1f0acbe771f6","Submitted":"2022-05-20","File":{"Uid":"dceb24b8a5c8472e970cec47f5286a02","Filename":"fee table.docx"}}],"Forecasts":[]}', '2022-01-20 12:40:41.952022', '2022-05-20 12:40:41.952023', '2022-05-20 12:45:31.179551', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (29, 'c854af9a33b64af0a96ed0a015bd51bd', 6, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"The ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and your objectives."},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the policy providers levy the fee monthly.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fee in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":""},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. They both enable the use of Model Portfolio Services from Discretionary Investment Managers. Aviva is one of the few providers who also allow you to split a single investment product over two different portfolios.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e","Text":"\u003cp\u003e(Please note that you still have £685.83 in the LF Equity Income C Acc fund within your ISA. This fund sits outside of any model. It is a closed fund, and as such, cannot be traded out of.)\u003c/p\u003e"},{"Type":"conclusions_advice_given","Intro":"\u003cp\u003eSince the last review, I recommended that you top up your existing pension with a single contribution and increase your regular contributions.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of {{ charge }}% per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18}],"ProviderDiscounts":[{"Id":"853f77c9c600486f99df1279a422314d","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.15}],"Policies":[{"Id":"5df6c59c35444eec88f9c9a30fc1e40f","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2044777-001","MonthlyContributions":1666,"StartValue":118356,"EndValue":130372,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"e1ac57bc57794246995aff127abe8fd6","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2044777-002","MonthlyContributions":1500,"StartValue":41233,"EndValue":65100,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":[{"Id":"d44ef4cb8cf647d3b85e1793029bc736","Name":"LF Equity Income C Acc","OcfFee":0.75,"ExAnteFee":0.38,"Modified":"2022-05-20 00:00:00 +0000 UTC","File":{"Uid":"360eabb104674bfdbe0bf6230a60fd46","Filename":"LF Equity Income.pdf"}}],"PolicyFunds":[{"Id":"0c4d78d2084e4ca689c7c5db11577217","FundId":"d44ef4cb8cf647d3b85e1793029bc736","PolicyId":"5df6c59c35444eec88f9c9a30fc1e40f","Proportion":0.0004}],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"1","Name":"LGT WMAdventurous","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.74,"WeightedExAnteFee":0.14,"Modified":"2022-05-20 00:00:00 +0000 UTC","File":{"Uid":"650dd8104504479497d6d8708b805952","Filename":"LGT WM Adventurous.pdf"}},{"Id":"b91b3aed61484c8a8a20d6100040e04a","Name":"Tatton Tracker Aggressive","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.12,"WeightedExAnteFee":0.06,"Modified":"2022-05-20 00:00:00 +0000 UTC","File":{"Uid":"fa17bb0ecff943218d5f4b1a2296254b","Filename":"tatton tracker aggressive.pdf"}}],"Portfolios":[{"Id":"37cff1a104d04d75adb981d198ec347d","PolicyId":"5df6c59c35444eec88f9c9a30fc1e40f","ModelId":"1","Proportion":0.4823},{"Id":"f8402b4531ab41c1b0f0ca03c22d341d","PolicyId":"5df6c59c35444eec88f9c9a30fc1e40f","ModelId":"b91b3aed61484c8a8a20d6100040e04a","Proportion":0.5173},{"Id":"22d1b5a00dfc4a7a813f92daa15fb1ed","PolicyId":"e1ac57bc57794246995aff127abe8fd6","ModelId":"1","Proportion":0.4862},{"Id":"daf4aad8801248a0996e8164181a184c","PolicyId":"e1ac57bc57794246995aff127abe8fd6","ModelId":"b91b3aed61484c8a8a20d6100040e04a","Proportion":0.5137}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"618df96d50d844db9444b052af397e74","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":7,"Label":"7 of 10 - Highest medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘highest medium’ risk profile shows that your willingness and ability to accept investment risk is well above average. A portfolio that matches this risk profile is likely to experience significant rises and falls in value. So, while there is strong potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly high- and very-high-risk investments, such as UK, overseas developed and emerging market shares. It is also expected to have a small amount of medium-risk investments such as Property as well as Sterling corporate bonds and global bonds including higher income types. Always check that you are comfortable with the investments that are included in your chosen portfolio.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"19c72caa7e2f42c59bfff3a59f9d4004","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"618df96d50d844db9444b052af397e74","Completed":"2022-02-16","Questionnaire":{"Uid":"22ddf2a3a17247e19f3edb5d8d23222d","Filename":"Client_Profiling_Report.pdf"}}],"FactFinds":[{"Id":"3083a610d2f1435ab2dae4c0a3f3af10","Submitted":"2022-05-20","File":{"Uid":"a72d782f3c474c59a15b75dea445d54a","Filename":"Fact find only.pdf"}}],"FeesReports":[{"Id":"1213941a6b114ca2884070e55ec7e6e7","Submitted":"2022-05-20","File":{"Uid":"c464d2071c5842d7b15cdb7bec88a06f","Filename":"feetable.docx"}}],"Forecasts":[]}', '2021-05-20 00:00:00', '2022-05-20 00:00:00', '2022-05-20 13:17:30.333272', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (30, '5f8e7150679b48069d7ae356d953e88f', 5, NULL, '2022-01-21 14:22:29.004726', '2022-05-21 14:22:29.004727', NULL, 'draft');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (35, '1a30b64212044807b8f45152bf130866', 2, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"The ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and your objectives."},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s,\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we looked after. The fee is expressed in terms of an annual percentage although, in most cases, the policy providers levy the fee monthly.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fee in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"introduction","Intro":"","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy\u003c/p\u003e","Text":""},{"Type":"conclusions_forecast","Intro":"\u003cp\u003eThis section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eOver the last year I have given you advice on the following specific points:\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eTopping up your ISA\u003c/li\u003e\u003cli\u003eSetting up a new GIA\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eWe have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.\u003c/p\u003e"},{"Type":"conclusions_goals","Intro":"\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of {{ charge }}% per year.\u003c/p\u003e"},{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""}],"ProviderCharges":[{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2},{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":1},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35},{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55}],"ProviderDiscounts":[{"Id":"0ec68f1eb6904fc3948fbf6d57aa7364","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"6beaec3191ba47db9e49ec33ac540c00","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"123456","MonthlyContributions":200,"StartValue":121311,"EndValue":132759,"Notes":"\u003cp\u003eblah\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"b5c4064889c74ab2b6a5ed2c0b683255","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"123","MonthlyContributions":0,"StartValue":100,"EndValue":1000,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"4d1d74ff96f745399d68eba1cfe64f13","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"456","MonthlyContributions":0,"StartValue":10000,"EndValue":12000,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":[{"Id":"338c91a2dcc943f29615148fc8734ff3","Name":"Fundsmith Equity","OcfFee":0.81,"ExAnteFee":0.09,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"057a51200a6a4b4993e9961c07b3d401","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","Proportion":1}],"Operators":[{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015},{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002}],"Models":[{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}},{"Id":"0","Name":"LGT Vestra Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}}],"Portfolios":[{"Id":"8d44508721954d708cbf437acd80bba9","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"2","Proportion":0.5},{"Id":"99eb4251f3a44eb59f1316f1ae6d0a64","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"0","Proportion":0.5},{"Id":"45f2436b75814f9bb8d3dc8b83a77544","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","ModelId":"0","Proportion":1}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"d84eadecc60f49958d5b90abbfc0809c","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2022-05-03","Questionnaire":{"Uid":"6c250cddf3d14468a4a5b4b63137dc88","Filename":"Client Profiling Report.pdf"}}],"FactFinds":[{"Id":"39cec7ea8d0d4abf843efb88de2ae05e","Submitted":"2022-06-09","File":{"Uid":"224de1f41aa9417aa0341f2601b05941","Filename":"PG FF.pdf"}}],"FeesReports":[{"Id":"46c84ca2478a4b51a0225c17f2865206","Submitted":"2022-06-09","File":{"Uid":"d7ca6cb0a77d47a2bebe99a3d893349e","Filename":"fees rep.docx"}}],"Forecasts":[{"Id":"3863392752fd4ef493d723f1f82cfd7f","Submitted":"2022-06-09","File":{"Uid":"1c812d90ac6e452db0ca6d79efcd5fbd","Filename":"chart.pdf"}}]}', '2021-01-18 00:00:00', '2022-01-17 00:00:00', '2022-06-09 21:12:59.799856', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (50, '6427484792644f399e3aa2633320e277', 8, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_goals","Intro":"\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":""},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour Aviva platform pension is a suitable vehicle to help you to meet your goals. Pensions are a tax efficient method of investing for the future. The Aviva scheme allows you to utilise the services of Model Portfolio Services (MPSs) from Discretionary Investment Managers. The Aviva platform is one of the few such platforms which enable the use of multiple MPSs within a single product.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e","Text":""},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse use of Aviva, Tatton and LGT Vestra WM.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eAlthough we have met and discussed your situation over the review period, I did not recommend any changes to the management of your Aviva pension.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003e(We did discuss your intention to increase pension investment, but we felt that this was best done through your workplace scheme at this time).\u003c/p\u003e"},{"Type":"profile_objectives","Intro":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your early 60s. That said, you may wish to continue working in a part-time capacity after that point.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e","Text":""}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0}],"ProviderDiscounts":[{"Id":"bf3f0738535a4bdd8b00c3bccdb7bb39","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.13}],"Policies":[{"Id":"1e4677bcd06e4c66a21bc59d8d22afc0","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2074121-001","MonthlyContributions":0,"StartValue":783316,"EndValue":755147,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":null,"PolicyFunds":[],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"63f2629afef0436090b3b211038870bb","Name":"LGT WM Growth","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.73,"WeightedExAnteFee":0.15,"Modified":"2022-07-29T00:00:00Z","File":{"Uid":"7ca79f0213464eeca32e9920d5559843","Filename":"LGT WM Growth.pdf"}},{"Id":"5c99ea3ce6e141d29cb9c064ed130a27","Name":"Tatton Core Aggressive","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.36,"WeightedExAnteFee":0.11,"Modified":"2022-07-29T00:00:00Z","File":{"Uid":"42710869837b4a5aa8bd061ec5274f1a","Filename":"Tatton Core Aggressive.pdf"}}],"Portfolios":[{"Id":"dbbff11c05a7445c8a16a4bd487e7db9","PolicyId":"1e4677bcd06e4c66a21bc59d8d22afc0","ModelId":"5c99ea3ce6e141d29cb9c064ed130a27","Proportion":0.6577},{"Id":"b653328637d249f881acbd9fbbf20162","PolicyId":"1e4677bcd06e4c66a21bc59d8d22afc0","ModelId":"63f2629afef0436090b3b211038870bb","Proportion":0.3256}],"RiskProviders":[{"Id":"ca1a7c11168a4918a08d0ad14ee89370","Name":"FE Analytics/eValue"}],"RiskLevels":[{"Id":"2e990787d80a4c64929f975b0686c3f4","RiskProviderId":"ca1a7c11168a4918a08d0ad14ee89370","Level":3,"Label":"3 - Moderate","Desc":"\u003cp\u003eYou are prepared to take a moderate amount of investment risk in order to increase the chance of achieving a positive return. Capital protection is less important to you than achieving a better return on the investment.A typical Moderate investor will usually invest in a variety of assets to obtain diversification and therefore reduce risk.\u003c/p\u003e\u003cp\u003eEquities and property, which can boost longer term returns but are associated with more risk, would often account for a higher proportion of assets than fixed interest gilts and bonds or cash. At shorter investment terms the proportion of higher risk assets is\u003c/p\u003e\u003cp\u003eusually reduced.The range of asset types helps reduce the overall risks while increasing the chance of better returns.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"5c21398cf4ed499fab0b66bcd6c2676c","RiskProviderId":"ca1a7c11168a4918a08d0ad14ee89370","RiskLevelId":"2e990787d80a4c64929f975b0686c3f4","Completed":"2020-06-23T00:00:00Z","Questionnaire":{"Uid":"5a2eec5a4b74444d8e77b8d911be7fbc","Filename":"ATRQPDF.pdf"}}],"FactFinds":[{"Id":"830b9dd0f7dc4b02b4da4c4d6e6c9cc7","Submitted":"2022-07-29T00:00:00Z","File":{"Uid":"04fc9f7a42ee4b9dba64fc9f7ffb9875","Filename":"FF.pdf"}}],"FeesReports":[{"Id":"00408c88bfe24023b4470f641a3e129d","Submitted":"2022-07-29T00:00:00Z","File":{"Uid":"572ff26148f945d2a830efbbdc9d6d6b","Filename":"Fee Table.docx"}}],"Forecasts":[]}', '2021-07-27 00:00:00', '2022-07-27 00:00:00', '2022-08-01 11:00:02.156015', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (53, '6936f426b50a4ecfacb28fe225b7d8c0', 7, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"fees_advice_fee","Intro":"","Text":"\u003cp\u003ePlease note that, due to a logging error, the fees which have actually been received in relation to your pension do not appear in the linked file. This error has now been rectified, so the actual fees received (including those received to date) will appear on any future reports.\u003c/p\u003e"},{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e","Text":""},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour Aviva platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. Both products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"\u003cul\u003e\u003cli\u003eI reviewed your existing pensions and I advised that you transfer them to a new policy on the Aviva platform.\u003c/li\u003e\u003cli\u003eI recommended that you invest £10,000 of the money you were holding on deposit for medium to long term capital growth in a Stocks and Shares ISA, also on the Aviva platform.\u003c/li\u003e\u003cli\u003eI recommended you commence regular contributions to both arrangements.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","Text":""},{"Type":"profile_objectives","Intro":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eYou have said that, ideally, you would like to aim for a retirement age of 60, but you realise that that may be unrealistic. Although you do not have a specific date in mind for retirement, you would still like to make financial plans for it.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e","Text":""},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse the continued use of Aviva, Brewin Dolphin and IBOSS Asset Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0}],"ProviderDiscounts":[],"Policies":[{"Id":"3e832f92bdb5468b90cf5c4e6816c5f3","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2618166-001","MonthlyContributions":500,"StartValue":10000,"EndValue":14851,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"53362e617f8140beac676d3756b52f89","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"AV2618166-002","MonthlyContributions":375,"StartValue":0,"EndValue":95510,"Notes":"\u003cp\u003eThe contribution given includes tax relief. Your direct debit is for £300 per month.\u003c/p\u003e","File":{"Uid":"","Filename":""}}],"Funds":null,"PolicyFunds":[],"Operators":[{"Id":"b02e6cc023e345b58e020137599118a9","Type":"dim","Name":"Brewin Dolphin","Fee":0.003},{"Id":"2e32d23126904aaeac119192fa388c0b","Type":"dim","Name":"IBOSS","Fee":0.002}],"Models":[{"Id":"27b1a7de42e04c3a98ca78e81083ce4b","Name":"IBOSS Portfolio 6","OperatorId":"2e32d23126904aaeac119192fa388c0b","WeightedOcfFee":0.57,"WeightedExAnteFee":0.17,"Modified":"2022-07-29T00:00:00Z","File":{"Uid":"c57e1fa908744cca84f8eb601c7a9046","Filename":"MPS-6.pdf"}},{"Id":"22b4ae832e074642b501bf8e4c9656a1","Name":"Brewin Dolphin Growth","OperatorId":"b02e6cc023e345b58e020137599118a9","WeightedOcfFee":0.43,"WeightedExAnteFee":0.16,"Modified":"2022-07-29T00:00:00Z","File":{"Uid":"94aec9f79fe14d01894e27eadb6895c4","Filename":"Brewin Dolphin-MPS_Growth_June_2022.pdf"}}],"Portfolios":[{"Id":"6d7a7ffcb34d4e2eae255a5e6382b9c6","PolicyId":"3e832f92bdb5468b90cf5c4e6816c5f3","ModelId":"27b1a7de42e04c3a98ca78e81083ce4b","Proportion":0.5},{"Id":"70f017e60d35447283be7f80a4045c05","PolicyId":"3e832f92bdb5468b90cf5c4e6816c5f3","ModelId":"22b4ae832e074642b501bf8e4c9656a1","Proportion":0.5},{"Id":"5381395150564441ba97b7ca0405f749","PolicyId":"53362e617f8140beac676d3756b52f89","ModelId":"27b1a7de42e04c3a98ca78e81083ce4b","Proportion":0.5},{"Id":"4f363919ef20419ba8ec0dbabac9eb46","PolicyId":"53362e617f8140beac676d3756b52f89","ModelId":"22b4ae832e074642b501bf8e4c9656a1","Proportion":0.5}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"6d9ea6f77c7c4388858bdff4c6a8f966","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2021-06-01T00:00:00Z","Questionnaire":{"Uid":"c6991c92c52a4096b8199b0b22821285","Filename":"Client_Profiling_Report.pdf"}}],"FactFinds":[{"Id":"2191a4f0e642499995d8260d2fd12987","Submitted":"2022-07-29T00:00:00Z","File":{"Uid":"0b87e1413f374a14baccfb41b181ac0e","Filename":"FF.pdf"}}],"FeesReports":[{"Id":"f4432cfd33994dd5b3eeaccd2db84728","Submitted":"2022-07-29T00:00:00Z","File":{"Uid":"33715cab34844d0ab3ddd073b8eb5179","Filename":"fee tables.docx"}}],"Forecasts":[]}', '2021-07-27 00:00:00', '2022-07-27 00:00:00', '2022-08-03 07:47:28.509678', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (56, 'd5e1e091e0a84c9fb2511eca6717a0e5', 10, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e","Text":""},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are all suitable vehicles to help you to meet your goals. The Aegon ARC pension and ISA are both tax efficient wrappers. (The GIA is taxable but there is only a residual amount of money held in this wrapper). All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eThe Aviva pensions, whilst not as flexible as the Aegon ones, are still appropriate tax efficient methods of investing for the long term benefit of your children.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e","Text":""},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse the use of Aviva, Aegon and Tatton Investment Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"\u003cp\u003eAlthough we have spoken and discussed your situation, I have not made any specific recommendations for changes to your portfolio over the review period.\u003c/p\u003e","Text":""},{"Type":"profile_objectives","Intro":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003cli\u003eYou would also like to make some investments on behalf of your children to give them a headstart with their own financial planning.\u003c/li\u003e\u003c/ul\u003e","Text":""},{"Type":"conclusions_action_points","Intro":"\u003cp\u003eWe discussed various plans, which you would like to implement later in the year, once you have received your next profit distribution:\u003c/p\u003e\u003cul\u003e\u003cli\u003eYou would like to increase the payments you are making on a regular basis to your children''s pensions. We also discussed transferring these policies to a more modern, platform based policy, which would allow you to use model portfolio services for these investments in the same way that you do for your own investments.\u003c/li\u003e\u003cli\u003eYou are intending to make an overpayment to your mortgage.\u003c/li\u003e\u003cli\u003eSubject to budget, you may also want to invest more money on a single contribution basis.\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eRight now, your advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e","Text":""}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"}],"PolicyProviders":[{"Id":"4ebdb61927e84a9d97b0e77ca7d6c211","Name":"Aviva","Pricing":"\u003cp\u003eAviva''s product fee for their personal pension is 0.7% per year. This is discounted based on the fund size according to the following table:\u003c/p\u003e\u003cp\u003eFund size (£)\t\t\tDiscount (% points)\u003c/p\u003e\u003cp\u003e0-£19,999\t\t\t\t0.00\u003c/p\u003e\u003cp\u003e£19,000-£29,999\t0.25\u003c/p\u003e\u003cp\u003e£30,000-£49,999\t0.25\u003c/p\u003e\u003cp\u003e£50,000-£99,000\t0.30\u003c/p\u003e\u003cp\u003e£100,000\tor more\t0.30\u003c/p\u003e","CustomPricing":""},{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""}],"ProviderCharges":[{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":0.001,"Sequence":4},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32,"Sequence":3},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35,"Sequence":2},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55,"Sequence":1},{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42,"Sequence":0}],"ProviderDiscounts":[],"Policies":[{"Id":"27f3f19524534781b9d10a3169d1f94f","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"4ebdb61927e84a9d97b0e77ca7d6c211","ExternalId":"TL94158560 (Alice)","MonthlyContributions":300,"StartValue":0,"EndValue":18000,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"93a8a12cd6244db99c8c9e9a892d84e9","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"4ebdb61927e84a9d97b0e77ca7d6c211","ExternalId":"TL94162098 (Charlotte)","MonthlyContributions":300,"StartValue":0,"EndValue":3710,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"399742441912472194824473c4307b6e","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"70950190","MonthlyContributions":0,"StartValue":0,"EndValue":596292,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"53952fa723914cbdaf9ed8f54e65d8bd","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"70950197","MonthlyContributions":1666,"StartValue":0,"EndValue":109427,"Notes":"","File":{"Uid":"","Filename":""}},{"Id":"b0de8a591d9340f9b025c6af979e1fa7","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"71004883","MonthlyContributions":0,"StartValue":0,"EndValue":1880,"Notes":"","File":{"Uid":"","Filename":""}}],"Funds":[{"Id":"c49632aff6ec41608f1d57cb50c3b219","Name":"Aviva Pensions Multi-asset Plus Fund IV","OcfFee":0.0001,"ExAnteFee":0.1,"Modified":"2022-08-03T00:00:00Z","File":{"Uid":"ede2c644b3b0442786a66be756157791","Filename":"Aviva_(Pension)_h-Av_Multi-asset_Plus_Fund_IV_S6.pdf"}}],"PolicyFunds":[{"Id":"1ba60dc8626f43ba909f049102b795fb","FundId":"c49632aff6ec41608f1d57cb50c3b219","PolicyId":"93a8a12cd6244db99c8c9e9a892d84e9","Proportion":1},{"Id":"4c69c1decf974c34ac3ed09c5b3d0bb0","FundId":"c49632aff6ec41608f1d57cb50c3b219","PolicyId":"27f3f19524534781b9d10a3169d1f94f","Proportion":1}],"Operators":[{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"5c99ea3ce6e141d29cb9c064ed130a27","Name":"Tatton Core Aggressive","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.36,"WeightedExAnteFee":0.11,"Modified":"2022-07-29T00:00:00Z","File":{"Uid":"42710869837b4a5aa8bd061ec5274f1a","Filename":"Tatton Core Aggressive.pdf"}}],"Portfolios":[{"Id":"cb4091bc859845af897d772f6b30f4b6","PolicyId":"b0de8a591d9340f9b025c6af979e1fa7","ModelId":"5c99ea3ce6e141d29cb9c064ed130a27","Proportion":1},{"Id":"88b4d7ca35bc4c018a41b23d4ab8f03f","PolicyId":"53952fa723914cbdaf9ed8f54e65d8bd","ModelId":"5c99ea3ce6e141d29cb9c064ed130a27","Proportion":1},{"Id":"047bb3d2bbe741f7bbd12bab773a05ed","PolicyId":"399742441912472194824473c4307b6e","ModelId":"5c99ea3ce6e141d29cb9c064ed130a27","Proportion":1}],"RiskProviders":[{"Id":"ca1a7c11168a4918a08d0ad14ee89370","Name":"FE Analytics/eValue"}],"RiskLevels":[{"Id":"5168b3da5a8440e5a44877e6d309eccc","RiskProviderId":"ca1a7c11168a4918a08d0ad14ee89370","Level":4,"Label":"4 - Moderate to Adventurous","Desc":"\u003cp\u003eYou are prepared to take a medium degree of risk with your investment/s in return for the prospect of improving longer term performance.Short term capital protection is not important to you andyou are willing to sacrifice some long term protection for the\u003c/p\u003e\u003cp\u003elikelihood of greater returns.A typical Moderate to Adventurous investor will be invested in equities but with other assets included to provide some diversification. There may be a small amount of specialised equities within the portfolio, which focus on a particular\u003c/p\u003e\u003cp\u003esector of the economy or relate to a particular market or industry. Specialised equities can boost longer term returns but are associated with more risk than standard type equities.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"98394f3b72e847a48a302c4b48ee027a","RiskProviderId":"ca1a7c11168a4918a08d0ad14ee89370","RiskLevelId":"5168b3da5a8440e5a44877e6d309eccc","Completed":"2020-06-22T00:00:00Z","Questionnaire":{"Uid":"c5851658edc448518087a8c122623de8","Filename":"ATRQPDF.pdf"}}],"FactFinds":[{"Id":"3a7ebbbe82fe4da88171fc97eb3a9925","Submitted":"2022-08-03T00:00:00Z","File":{"Uid":"ed4288391a69409fa94819fefe953869","Filename":"FF.pdf"}}],"FeesReports":[{"Id":"5ebb1f87f7eb45aa802576bcc8e7a6c2","Submitted":"2022-08-03T00:00:00Z","File":{"Uid":"fa1b7a2bf5b04225b12951f8e752cefc","Filename":"Fees table.docx"}}],"Forecasts":[]}', '2021-08-03 00:00:00', '2022-08-03 00:00:00', '2022-08-10 11:24:31.557657', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (47, '4d5a5f072326427cb43962eae59844d1', 2, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_goals","Intro":"\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003eYou have confirmed that you are happy with the generalised nature of your financial planning thus far.\u003c/p\u003e","Text":""},{"Type":"conclusions_forecast","Intro":"\u003cp\u003eThis section contains a cashflow forecasting model which I have explained to you. If you would like more detail on this feel free to ask.\u003c/p\u003e","Text":""},{"Type":"conclusions_advice_given","Intro":"","Text":"\u003cp\u003eOver the last year I have given you advice on the following specific points:\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eTopping up your ISA\u003c/li\u003e\u003cli\u003eSetting up a new GIA\u003c/li\u003e\u003c/ul\u003e\u003cp\u003eWe have also discussed the possibilities for re-mortgaging when your introductory fixed rate period ends.\u003c/p\u003e"},{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your use of Aviva, Aegon, LGT Vestra and Tatton Investment Management.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e","Text":""},{"Type":"conclusions_ongoing_suitability","Intro":"\u003cp\u003eYour policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy\u003c/p\u003e","Text":""},{"Type":"introduction","Intro":"\u003cp\u003eblah\u003c/p\u003e","Text":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"}],"PolicyTypes":[{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"},{"Id":"2ebd7784c381408790f5a5500c553ae7","Name":"GIA"},{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"},{"Id":"78e94fd5ec6e4a40aad451eed77a628c","Name":"Aegon","Pricing":"\u003cp\u003eAegon operates a tiered charging structure. This has been summarised below. The tiers incorporate the cumulative fund value of your pension, ISA and GIA. As the total fund size grows, the platform charge, in percentage terms decreases.\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e","CustomPricing":""}],"ProviderCharges":[{"Id":"5cbed389f63f4026923297cff803efd9","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"200,000-300,000","Charge":0.18,"Sequence":0},{"Id":"fe54b4b00bf64b8dafb906bd06ebec19","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"\u003e400,000","Charge":0.05,"Sequence":0},{"Id":"0403b42c3d16402086d2dada470c87d6","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"300,000-400,000","Charge":0.14,"Sequence":0},{"Id":"fcf3111e932a4bde905454e3841355de","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"100,000-200,000","Charge":0.2,"Sequence":0},{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"ba232747473b4f80ae173527c4f69a1b","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"\u003e250,000","Charge":0.001,"Sequence":4},{"Id":"a309933b03c74b0ba574dbaab87921b2","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"100,000-249,999","Charge":0.32,"Sequence":3},{"Id":"7751d17b0def4f92a789fa08d0696e50","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"50,000-99,000","Charge":0.35,"Sequence":2},{"Id":"405bdd23fad94846a43154e442a0a0fa","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"30,000-49,999","Charge":0.55,"Sequence":1},{"Id":"1c2562ac68414217bdc7a6a9b260752e","ProviderId":"78e94fd5ec6e4a40aad451eed77a628c","Desc":"0-29,999","Charge":0.42,"Sequence":0}],"ProviderDiscounts":[{"Id":"0ec68f1eb6904fc3948fbf6d57aa7364","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","Discount":0.18}],"Policies":[{"Id":"6beaec3191ba47db9e49ec33ac540c00","PolicyTypeId":"7ec08af90397470285aef69c5f5b6a86","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"123456","MonthlyContributions":200,"StartValue":121311,"EndValue":132759,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"292975c4738e487c81eb2997a2acbe0b","Filename":"test.txt"}},{"Id":"b5c4064889c74ab2b6a5ed2c0b683255","PolicyTypeId":"2ebd7784c381408790f5a5500c553ae7","PolicyProviderId":"78e94fd5ec6e4a40aad451eed77a628c","ExternalId":"123","MonthlyContributions":0,"StartValue":41358,"EndValue":48659,"Notes":"\u003cp\u003eThis policy was transferred to Aegon as part of block transfer. It has protected tax-free cash which is why it couldn''t also be transferred to Aviva\u003c/p\u003e","File":{"Uid":"","Filename":""}},{"Id":"4d1d74ff96f745399d68eba1cfe64f13","PolicyTypeId":"ae132a8a68c94f2a8a20cd2268592991","PolicyProviderId":"b7f8f4e5104043429c5993be7fdf930d","ExternalId":"456","MonthlyContributions":0,"StartValue":10000,"EndValue":12000,"Notes":"\u003cp\u003e\u003cbr\u003e\u003c/p\u003e","File":{"Uid":"","Filename":""}}],"Funds":[{"Id":"338c91a2dcc943f29615148fc8734ff3","Name":"Fundsmith Equity","OcfFee":0.81,"ExAnteFee":0.09,"Modified":"","File":{"Uid":"","Filename":""}},{"Id":"4c6f2e04f4204cc484563b2ad30b5dd6","Name":"Invesco High Income","OcfFee":0.67,"ExAnteFee":0.11,"Modified":"","File":{"Uid":"","Filename":""}}],"PolicyFunds":[{"Id":"057a51200a6a4b4993e9961c07b3d401","FundId":"338c91a2dcc943f29615148fc8734ff3","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5},{"Id":"7aeec1c0eea7409f891e618919b9a8f9","FundId":"4c6f2e04f4204cc484563b2ad30b5dd6","PolicyId":"b5c4064889c74ab2b6a5ed2c0b683255","Proportion":0.5}],"Operators":[{"Id":"598f683493e34cdbb0f786a06f2a92ea","Type":"dim","Name":"LGT WM","Fee":0.002},{"Id":"e1266d5122644b69899fe52cb9c8c0a0","Type":"dim","Name":"Tatton","Fee":0.0015}],"Models":[{"Id":"0","Name":"LGT WM Balanced","OperatorId":"598f683493e34cdbb0f786a06f2a92ea","WeightedOcfFee":0.58,"WeightedExAnteFee":0.14,"Modified":"","File":{"Uid":"18f06c0c6c1548c8a073e383e7d27bc1","Filename":"LGT Vestra Balanced.pdf"}},{"Id":"2","Name":"Tatton Core Active","OperatorId":"e1266d5122644b69899fe52cb9c8c0a0","WeightedOcfFee":0.55,"WeightedExAnteFee":0.12,"Modified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}}],"Portfolios":[{"Id":"45f2436b75814f9bb8d3dc8b83a77544","PolicyId":"4d1d74ff96f745399d68eba1cfe64f13","ModelId":"0","Proportion":1},{"Id":"99eb4251f3a44eb59f1316f1ae6d0a64","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"0","Proportion":0.5},{"Id":"8d44508721954d708cbf437acd80bba9","PolicyId":"6beaec3191ba47db9e49ec33ac540c00","ModelId":"2","Proportion":0.5}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"0eb1bf23a9cb42f4abd6ce303b20f498","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":6,"Label":"6 of 10 - High medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"d84eadecc60f49958d5b90abbfc0809c","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"0eb1bf23a9cb42f4abd6ce303b20f498","Completed":"2022-05-03T00:00:00Z","Questionnaire":{"Uid":"6c250cddf3d14468a4a5b4b63137dc88","Filename":"Client Profiling Report.pdf"}}],"FactFinds":[{"Id":"39cec7ea8d0d4abf843efb88de2ae05e","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"224de1f41aa9417aa0341f2601b05941","Filename":"PG FF.pdf"}},{"Id":"2267d2ddd9c6475d93adcc1be58613e9","Submitted":"2022-07-14T00:00:00Z","File":{"Uid":"4f4c6c9025ec48faa8104cc4a1b71473","Filename":"chart.pdf"}}],"FeesReports":[{"Id":"46c84ca2478a4b51a0225c17f2865206","Submitted":"2022-06-09T00:00:00Z","File":{"Uid":"d7ca6cb0a77d47a2bebe99a3d893349e","Filename":"fees rep.docx"}}],"Forecasts":[{"Id":"79334283414b46829202a2780723fb36","Submitted":"2022-07-13T00:00:00Z","File":{"Uid":"257a1784e0704825adb63cfc3aed26ad","Filename":"chart.pdf"}}]}', '2022-07-24 00:00:00', '2022-07-24 00:00:00', '2022-08-17 14:17:54.753525', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (43, 'beb06578a8d44aa7ac4e65a4deecafb4', 1, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice periodically assesses the quality of the providers which you are using. blah\u003c/p\u003e","Text":"\u003cp\u003eHowever, in your case, we don''t actually give a toss.\u003c/p\u003e"},{"Type":"introduction","Intro":"","Text":"\u003cp\u003etest\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"}],"PolicyTypes":[{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4