dified":"","File":{"Uid":"7937ed73b98244fdbc8f7639875f4a01","Filename":"FundFactLiterature.pdf"}}],"Portfolios":[{"Id":"761dcc9457c5418bace91821a4efeecb","PolicyId":"1e328d3daa2844cfb8e61475e2b93e5d","ModelId":"0","Proportion":1},{"Id":"d0ea24231c86494d880d38730e5a3f0a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"1","Proportion":0.6},{"Id":"ee0e475ab10e466c9e2b20107e11c50a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"2","Proportion":0.4}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"76d9f542b3d44e19b74c8276dc3d9ece","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":4,"Label":"4 of 10 - Lowest Medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘lowest medium’ risk profile shows that your willingness and ability to accept investment risk is just below average. A portfolio matching this risk profile is likely to experience both rises and falls in value. So, while there is potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly low- and medium-risk investments, including money market investments, government bonds, Sterling corporate bonds, and a mix of global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares but held mainly in UK and other developed markets. Small amounts in other higher-risk investments may also be included. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"939a3b96046e446c8d633ed937d878ab","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","RiskLevelId":"76d9f542b3d44e19b74c8276dc3d9ece","Completed":"2022-05-18T00:00:00Z","Questionnaire":{"Uid":"764a9e65cfd049b08ad51c68db47cc04","Filename":"sample.png"}}],"FactFinds":[{"Id":"9c614ebc14604a54a910925507bdc1ca","Submitted":"2022-04-26T00:00:00Z","File":{"Uid":"5cb8b5bd8c69408795ae535660157600","Filename":"PXL_20220408_005403964.jpg"}}],"FeesReports":[{"Id":"6fce555dc0034858bc64bd36235a9661","Submitted":"2022-04-29T00:00:00Z","File":{"Uid":"534944f5567446f582f4b9ba6370cd14","Filename":"PXL_20220408_005429828.MP.jpg"}}],"Forecasts":[]}', '2022-08-12 00:00:00', '2022-10-15 00:00:00', '2022-09-01 22:53:23.73942', 'final');
INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (57, '0dcb0c25628c443e8f42c9f6c4da2a24', 1, '{"ModulePresets":[{"ModuleType":"introduction","Text":"This dashboard consists of a high-level overview of your situation and the policies and investments which are under the care of Integral Advice. It is designed to complement any discussions given in person, over the phone or by email, but doesn’t cover any specific advice points. These are covered by individualised suitability reports issued at the appropriate times."},{"ModuleType":"profile","Text":"\u003cp\u003eThe ongoing suitability of the assets and policies which are under Integral Advice’s advice is based upon a thorough understanding of your situation at all times. This section includes a consideration of your current personal and financial circumstances, your attitude to investment risk and the overarching goals of your financial planning.\u003c/p\u003e"},{"ModuleType":"profile_fact_find","Text":"Please click the link to view the latest Personal \u0026 Financial Review document."},{"ModuleType":"profile_risk","Text":"Your attitude to risk has been judged to be…XXXX. This is based on the outcome of a questionnaire and discussion, which are linked below."},{"ModuleType":"profile_objectives","Text":"\u003cp\u003eWe have identified some overall aims and goals for your financial planning. The details of these are listed below.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cul\u003e\u003cli\u003eAlthough you do not have a specific date or age in mind for retirement, you would like to you have the option of being able to retire in your 60s.\u003c/li\u003e\u003cli\u003eTo reach this goal, you would like to have built up a sufficient portfolio such that you can live on your assets alone.\u003c/li\u003e\u003cli\u003eYou are keen to make use of the tax allowances and reliefs which are available to you.\u003c/li\u003e\u003cli\u003eYou wish to meet your long term goals by investing for capital growth.\u003c/li\u003e\u003cli\u003eYou are happy to accept some volatility and risk in return for asset growth in excess of that which you could obtain from bank interest and in excess of inflation.\u003c/li\u003e\u003c/ul\u003e"},{"ModuleType":"policy_valuations","Text":"\u003cp\u003eThe value of your assets and policies may have changed since the last time we reviewed your situation. The following table should give you an indication of your progress in this regard. A change in value can either arise as a result of market movement or as a result of contributions and withdrawals made.\u003c/p\u003e"},{"ModuleType":"fees","Text":"\u003cp\u003eAny assets or policies which are the subject of our ongoing advice will incur fees from several parties. These are listed in the tabs within this section.\u003c/p\u003e"},{"ModuleType":"fees_advice_fee","Text":"\u003cp\u003eThe Integral Advice Ongoing Service Charge is charged on the assets and polices we look after. The fee is expressed in terms of an annual percentage although, in most cases, the fees are actually deducted on a monthly basis.\u003c/p\u003e\u003cp\u003eThe table shows an approximation of the fees in monetary terms, based on the current valuations of each of the policies and assets to which it applies.\u003c/p\u003e\u003cp\u003eActual fees which have been received by Integral Advice during the review period can be seen by downloading the linked report. This will also include any one-off or transactional fees which may have been charged. (Note that fees received within the last 4 to 6 weeks which haven’t been logged yet may not be included in the summary).\u003c/p\u003e"},{"ModuleType":"fees_policy_fees","Text":"\u003cp\u003eEach investment platform or policy provider has their own set of fees. These are detailed below.\u003c/p\u003e"},{"ModuleType":"fees_fund_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time. The following table summarises the current state of those fees, as disclosed by the fund managers.\u003c/p\u003e"},{"ModuleType":"fees_portfolio_level","Text":"\u003cp\u003eEach of the funds you are investing in has an Ongoing Charges Figure attached to it. This includes the fund manager''s fees and certain other costs, such as administration, marketing and regulation. There are also transactional fees which are incurred in the fund’s operation. The transactional fees shown are the “ex-ante” fees. This means they are anticipated fees, which may differ slightly from those which are actually incurred (the “ex-post” fees). Both OCF and transaction fees change over time.\u003c/p\u003e\u003cp\u003eThe charges shown in the following table are the weighted averages of those charges which apply to each of the underlying funds which make up your portfolio(s).\u003c/p\u003e"},{"ModuleType":"fees_dim","Text":"\u003cp\u003eDiscretionary Investment Managers (DIMs) levy a fee for operating their Model Portfolios Services. These are reported in the Portfolio-Level tab on a policy by policy basis. The table below aggregates these figures so that you can see each DIM in isolation. These charges are not, therefore, in addition to those disclosed on the Portfolio-Level tab. They are reported here for your convenience only.\u003c/p\u003e"},{"ModuleType":"conclusions_goals","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eDelete the following paragraphs as appropriate and add further detail if there are specific objectives:\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eDuring our discussions we have identified the following objectives. Achieving these specific objectives should enable you to meet your goals.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives. At this stage, your planning is constrained by your financial planning budget.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eAlthough we have identified the overall goals of your financial planning, we haven''t created any specific objectives.\u0026nbsp;You have confirmed that you are happy with the generalised nature of your financial planning at this stage.\u003c/p\u003e"},{"ModuleType":"conclusions_due_diligence","Text":"\u003cp\u003eIntegral Advice conducts periodic due diligence on the platform and model service providers that you use. On the basis of this research, I am happy to continue to endorse your current arrangements.\u003c/p\u003e\u003cp\u003ePlease refer to your Suitability Reports for the reasons why I recommended each of your policy providers and portfolio managers.\u003c/p\u003e\u003cp\u003eFinally, I would like to draw your attention to the fact that my recommendations may change over time and your products and portfolios will form part of future reviews.\u003c/p\u003e"},{"ModuleType":"conclusions_ongoing_suitability","Text":"\u003cp\u003e\u003cstrong\u003e\u003cem\u003eAdvisers should replace this text with the reasons they feel that the current policies are suitable to meet their own objectives and the reasons they are suitable for helping the client meet their goals.\u003c/em\u003e\u003c/strong\u003e\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eYour .... platform policies are suitable vehicles to help you to meet your goals. The pension and ISA are both tax efficient wrappers. All three products enable the use of Model Portfolio Services from Discretionary Investment Managers.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor further information behind the specific recommendations of these products, I refer you back to the Suitability Report which you received at the time of commencing each policy.\u003c/p\u003e"},{"ModuleType":"conclusions_action_points","Text":"\u003cp\u003eYour advice requirements are currently up to date, and there is nothing to action at this stage. Please get in touch if there is anything you are concerned about or if you have any questions on the contents of this report.\u003c/p\u003e"}],"Modules":[{"Type":"conclusions_due_diligence","Intro":"\u003cp\u003eIntegral Advice periodically assesses the quality of the providers which you are using. blah\u003c/p\u003e","Text":"\u003cp\u003eHowever, in your case, we don''t actually give a toss.\u003c/p\u003e"},{"Type":"introduction","Intro":"","Text":"\u003cp\u003etest\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e"}],"PolicyTypes":[{"Id":"ae132a8a68c94f2a8a20cd2268592991","Name":"ISA"},{"Id":"7ec08af90397470285aef69c5f5b6a86","Name":"Pension"}],"PolicyProviders":[{"Id":"b7f8f4e5104043429c5993be7fdf930d","Name":"Aviva Wrap","Pricing":"\u003cp\u003eAviva levy a platform fee for their pensions, on a tiered basis, according to the following table:\u003c/p\u003e\u003cp\u003e{{ table }}\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eFor ISAs and GIAs (General Investment Accounts), they charge 0.25% per year.\u003c/p\u003e","CustomPricing":"\u003cp\u003eIn your case, we have obtained a special pricing deal from Aviva, which replaces their usual tiered charging structure with a single annual percentage charge of\u003cstrong\u003e {{ charge }}%\u003c/strong\u003e per year.\u003c/p\u003e"}],"ProviderCharges":[{"Id":"78bcbb4251464ae5b991753a95440eab","ProviderId":"b7f8f4e5104043429c5993be7fdf930d","Desc":"0-100,000","Charge":0.3,"Sequence":0},{"Id":"fcf3111e932a4