00:00:00Z","File":{"Uid":"650dd8104504479497d6d8708b805952","Filename":"LGT WM Adventurous.pdf"}}],"Portfolios":[{"Id":"761dcc9457c5418bace91821a4efeecb","PolicyId":"1e328d3daa2844cfb8e61475e2b93e5d","ModelId":"0","Proportion":1},{"Id":"d0ea24231c86494d880d38730e5a3f0a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"1","Proportion":0.6},{"Id":"ee0e475ab10e466c9e2b20107e11c50a","PolicyId":"432750f27b7343a0bccfbf19b50937a4","ModelId":"2","Proportion":0.4}],"RiskProviders":[{"Id":"856a5d560b5849a98e682177ba22a24c","Name":"Dynamic Planner"}],"RiskLevels":[{"Id":"76d9f542b3d44e19b74c8276dc3d9ece","RiskProviderId":"856a5d560b5849a98e682177ba22a24c","Level":4,"Label":"4 of 10 - Lowest Medium","Desc":"\u003cp\u003eIt’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘lowest medium’ risk profile shows that your willingness and ability to accept investment risk is just below average. A portfolio matching this risk profile is likely to experience both rises and falls in value. So, while there is potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.\u003c/p\u003e\u003cp\u003e\u003cbr\u003e\u003c/p\u003e\u003cp\u003eA portfolio for this risk profile is most likely to contain mainly low- and medium-risk investments, including money market investments, government bonds, Sterling corporate bonds, and a mix of global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares but held mainly in UK and other developed markets. Small amounts in other higher-risk investments may also be included. As a result, you should always check that you are comfortable with what’s included.\u003c/p\u003e"}],"RiskAssessments":[{"Id":"939a3b96046e446c8d633ed937d878ab","RiskProviderId":"85