INSERT INTO public.reviews (id, uid, client_id, report, start_date, end_date, finalized_date, state) OVERRIDING SYSTEM VALUE VALUES (58, 'ee1208a5587a4e2b8b33f175cc0c7a26', 2, NULL, '2022-09-05 00:00:00', '2022-09-05 00:00:00', NULL, 'draft');
INSERT INTO public.risk_providers (id, uid, name, "timestamp") OVERRIDING SYSTEM VALUE VALUES (1, '856a5d560b5849a98e682177ba22a24c', 'Dynamic Planner', '2022-04-17 21:21:41.757');
INSERT INTO public.risk_providers (id, uid, name, "timestamp") OVERRIDING SYSTEM VALUE VALUES (2, 'ca1a7c11168a4918a08d0ad14ee89370', 'FE Analytics/eValue', '2022-04-17 21:21:46.326');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (5, 'b0ecb533109b4c5b8bfc6c078e55de26', 1, 3, '3 of 10 - Low', '<p>A ‘low’ risk profile shows that your willingness and ability to accept investment risk is below average. Any falls in the value of a portfolio that matches this risk profile should usually be small. However, potential returns are also likely to be modest. So, if inflation (the rate at which the prices of goods and services rise) is higher than the rate earned on the investment, the spending power of your money will be reduced.</p><p><br></p><p>A target portfolio for this risk profile is most likely to contain mainly low-risk and some medium-risk investments, including money market investments, government bonds, UK corporate bonds, global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares, held mainly in the UK but with smaller amounts in other developed markets as well as other higher-risk investments. As a result, you should always check that you are comfortable with what’s included.</p>', '2022-05-03 18:40:10.130999');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (2, 'ca242f73d2dd44099cf5be3c2267640f', 1, 2, '2 of 10 - Very Low', '<p>A ‘very low’ risk profile shows that your willingness and ability to accept investment risk is well below average. Any falls in the value of a portfolio that matches this risk profile should be very small. However, potential returns are also likely to be modest. So, if inflation (the rate at which the prices of goods and services rise) is higher than the rate earned on the investment, the spending power of your money will be reduced.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain mainly low-risk investments, including money market investments and government bonds. It will also be expected to contain some other medium and high-risk investments, such as property, sterling corporate bonds, global bonds as well as shares held usually in the UK. As a result, you should always check that you are comfortable with what’s included.</p>', '2022-04-17 21:25:11.882');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (6, '76d9f542b3d44e19b74c8276dc3d9ece', 1, 4, '4 of 10 - Lowest Medium', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘lowest medium’ risk profile shows that your willingness and ability to accept investment risk is just below average. A portfolio matching this risk profile is likely to experience both rises and falls in value. So, while there is potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain mainly low- and medium-risk investments, including money market investments, government bonds, Sterling corporate bonds, and a mix of global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares but held mainly in UK and other developed markets. Small amounts in other higher-risk investments may also be included. As a result, you should always check that you are comfortable with what’s included.</p>', '2022-05-05 09:50:28.996635');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (7, '0a03fafd4a034300a48f0c9b781dfbad', 1, 5, '5 of 10 - Low medium', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘low medium’ risk profile shows that your willingness and ability to accept investment risk is about average. A portfolio that matches this risk profile is likely to experience both rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain low-, medium- and high-risk investments, including money market investments, government bonds, Sterling corporate bonds and global bonds as well as Property. It will also be expected to contain some high-risk investments such as shares, but held mainly in UK and other developed markets, and also a small amount in other higher-risk investments such as shares in emerging markets. As a result, you should always check that you are comfortable with what’s included.</p>', '2022-05-05 09:51:32.695286');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (8, '0eb1bf23a9cb42f4abd6ce303b20f498', 1, 6, '6 of 10 - High medium', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high medium’ risk profile shows that your willingness and ability to accept investment risk is slightly above average. A portfolio that matches this risk profile is likely to experience some significant rises and falls in value. So, while there is good potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is likely to fall in value from time to time, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain mainly medium- and high-risk investments, including Sterling corporate bonds and global bonds including higher income types as well as Property and shares. The shares are expected to be held mainly in the UK and other developed markets, but there is also likely to be some in higher-risk emerging markets. As a result, you should always check that you are comfortable with what’s included.</p>', '2022-05-05 09:52:01.418535');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (9, '618df96d50d844db9444b052af397e74', 1, 7, '7 of 10 - Highest medium', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘highest medium’ risk profile shows that your willingness and ability to accept investment risk is well above average. A portfolio that matches this risk profile is likely to experience significant rises and falls in value. So, while there is strong potential for returns from your investment to match or go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment could fall in value from time to time, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain mainly high- and very-high-risk investments, such as UK, overseas developed and emerging market shares. It is also expected to have a small amount of medium-risk investments such as Property as well as Sterling corporate bonds and global bonds including higher income types. Always check that you are comfortable with the investments that are included in your chosen portfolio.</p>', '2022-05-05 09:56:41.646997');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (10, '578113d473484b1bbb9903f29dc4c0a6', 1, 8, '8 of 10 - High', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘high’ risk profile shows that you are willing and able to take a high level of risk with your investments. A portfolio that matches this risk profile is highly likely to experience both significant rises and falls in value. So, although there is very strong potential for returns from your investment to go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is very likely to fall in value from time to time, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain high- and very-high-risk investments such as UK, overseas developed and emerging market shares. There is also likely to be a small amount in medium-risk investments such as Property and higher-income types of global bonds. Always check that you are comfortable with the investments that are included in your chosen portfolio.</p>', '2022-05-05 09:57:07.400198');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (11, 'cd1c4e9b2bf741978f3b1020f91ed665', 1, 9, '9 of 10 - Very high', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘very high’ risk profile shows that you are willing and able to take a very high level of risk with your investments. A portfolio invested to match this risk profile is highly likely to experience both significant rises and falls in value. So, although there is very strong potential for returns from your investment to go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), you also need to accept that your investment is very likely to fall in value from time to time, particularly in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain high- and very-high-risk investments, such as UK, overseas developed and emerging market shares. Always check that you are comfortable with the investments that are included in your chosen portfolio.</p>', '2022-05-05 09:57:32.595637');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (12, '5589669b76f342ef98816329a8215f1a', 1, 10, '10 of 10 - Highest', '<p>It’s important that your investment portfolio matches your willingness and ability to take investment risk. A ‘highest’ risk profile shows that you are willing and able to take an extremely high level of risk with your investments. A portfolio invested to match this risk profile will probably experience very significant rises and falls in value. So, although there is extremely strong potential for returns from your investment to go above the rate of inflation (in other words, the rate at which the prices of goods and services rise), it is very likely that your investment will fall sharply in value from time to time, especially in the short term.</p><p><br></p><p>A portfolio for this risk profile is most likely to contain very-high-risk investments such as emerging market shares and a small amount in high-risk investments such as shares in UK and overseas developed markets. Always check that you are comfortable with the investments that are included in your chosen portfolio.</p>', '2022-05-05 09:57:57.342294');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (4, '2e990787d80a4c64929f975b0686c3f4', 2, 3, '3 - Moderate', '<p>You are prepared to take a moderate amount of investment risk in order to increase the chance of achieving a positive return. Capital protection is less important to you than achieving a better return on the investment.A typical Moderate investor will usually invest in a variety of assets to obtain diversification and therefore reduce risk.</p><p>Equities and property, which can boost longer term returns but are associated with more risk, would often account for a higher proportion of assets than fixed interest gilts and bonds or cash. At shorter investment terms the proportion of higher risk assets is</p><p>usually reduced.The range of asset types helps reduce the overall risks while increasing the chance of better returns.</p>', '2022-04-17 21:25:30.988');
INSERT INTO public.risk_levels (id, uid, risk_provider_id, level, label, "desc", "timestamp") OVERRIDING SYSTEM VALUE VALUES (15, '5168b3da5a8440e5a44877e6d309eccc', 2, 4, '4 - Moderate to Adventurous', '<p>You are prepared to take a medium degree of risk with your investment/s in return for the prospect of improving longer term performance.Short term capital protection is not important to you andyou are willing to sacrifice some long term protection for the</p><p>likelihood of greater returns.A typical Moderate to Adventurous investor will be invested in equities but with other assets included to provide some diversification. There may be a small amount of specialised equities within the portfolio, which focus on a particular</p><p>sector of the economy or relate to a particular market or industry. Specialised equities can boost longer term returns but are associated with more risk than standard type equities.</p>', '2022-08-03 09:25:51.765585');
INSERT INTO public.risk_assessments (id, uid, client_id, risk_level_id, questionnaire_file_id, completed, "timestamp") OVERRIDING SYSTEM VALUE VALUES (1, '15db59ebf6a84ad6ac0e5fc543a4c852', 4, 9, 11, '2021-02-21 00:00:00', '2022-05-17 18:22:14.716626');
