INSERT INTO public.risk_assessments (id, uid, client_id, risk_level_id, questionnaire_file_id, completed, "timestamp") OVERRIDING SYSTEM VALUE VALUES (10, '98394f3b72e847a48a302c4b48ee027a', 10, 15, 80, '2020-06-22 00:00:00', '2022-08-03 09:24:20.221568');
